use std :: process :: Command ; use std :: time :: Instant ; use std :: fs ; fn benchmark_mathematical_operations_performance () -> BenchmarkResult { let start = Instant :: now () ; let mut successful_math_operations = 0 ; for _i in 0 .. 4 { match Command :: new ("./simple_repository_mathematical_atlas") . output () { Ok (output) => { if output . status . success () { match fs :: read_to_string ("repository_atlas_output/simple_complete_atlas.md") { Ok (content) => { if content . contains ("Family Distribution") && content . contains ("Complexity Statistics") { successful_math_operations += 1 ; } } Err (_) => { } } } } Err (_) => { } } } let duration = start . elapsed () ; if successful_math_operations >= 3 { BenchmarkResult :: new ("Mathematical Operations Performance" . to_string () , duration . as_millis () as u64 , 4 , true , None) } else { BenchmarkResult :: new ("Mathematical Operations Performance" . to_string () , duration . as_millis () as u64 , 4 , false , Some (format ! ("Only {} successful mathematical operations out of 4" , successful_math_operations))) } }